window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d4edf3069d283f67"]={"versions": [{"id": "FIG-d4edf3069d283f67", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR-Software-Architektur (Classic Platform / Behavioral Modeling Interaktion). Das Diagramm spezifiziert die strukturelle Einbettung von Kommunikationsspezifikationen (<code>ServerComSpec</code>) an Bereitstellungs-Ports (<code>PPortPrototype</code>) innerhalb von Komponenten-Typen sowie die Import-Beziehung aus dem Verhaltensmodellierungs-Kontext (<code>BM Environment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metamodell-Klassen, Pakete und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Aggregiert über eine Komposition mit Rollenbezeichnung <code>+component</code> und Kardinalität <code>0..*</code> die Port-Prototypen (<code>+ports</code>).</li>\n<li><code>Components::PortPrototype</code>: Abstrakte Basisklasse, erbt von <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code> und <code>PropertyEvaluator</code>.</li>\n<li><code>Components::PPortPrototype</code>: Spezialisiert <code>Components::PortPrototype</code> (Generalisierung) und aggregiert über eine Komposition mit Rollenbezeichnung <code>+comSpec</code> und Kardinalität <code>0..*</code> Kommunikationsspezifikationen vom Typ <code>Communication::PPortComSpec</code>.</li>\n<li><code>Communication::PPortComSpec</code>: Abstrakte Basisklasse für Bereitstellungs-Port-Spezifikationen.</li>\n<li><code>Communication::ServerComSpec</code>: Spezialisiert <code>Communication::PPortComSpec</code> (Generalisierung). Besitzt das Attribut <code>+ queueLength: Int</code>.</li>\n<li><code>BM Environment</code> (Stereotyp bzw. Paket-Herkunft <code>(from Behavior Modeling)</code>): Referenziert <code>Communication::PPortComSpec</code> über eine Abhängigkeit (<code>&lt;&lt;dependency&gt;&gt;</code>) und importiert <code>Communication::ServerComSpec</code> über eine gerichtete Abhängigkeit mit dem Stereotyp <code>&lt;&lt;import&gt;&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeit- oder Sequenzabläufe. Die funktionale Semantik definiert zur Entwurfs- bzw. Konfigurationszeit, dass eine serverseitige Client-Server-Schnittstelle über einen <code>PPortPrototype</code> eine Pufferkapazität (<code>queueLength</code>) für eingehende Aufrufe vorhält, welche von der Modellierungsumgebung (<code>BM Environment</code>) für die Generierung oder Kopplung von Verhaltensmodellen importiert und ausgewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für AUTOSAR-Autorensysteme, Generatoren und Verhaltensmodellierungs-Werkzeuge. <code>ServerComSpec</code> definiert die Warteschlangenlänge (<code>queueLength</code>) für Client-Server-Operationen am Server-Port. Werkzeuge der Verhaltensmodellierung (<code>BM Environment</code>) müssen bei der Schnittstellen-Transformation oder Codegenerierung diesen Integer-Wert auswerten, um die Pufferung gleichzeitiger oder asynchroner Client-Aufrufe spezifikationskonform zu dimensionieren. Fehlt eine <code>ServerComSpec</code> oder ist <code>queueLength</code> nicht definiert, greifen plattformspezifische Standardwerte des RTE-Generators.</p>"}, {"id": "FIG-8b8675688b79fd7d", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR-Software-Architektur (Classic Platform / Behavioral Modeling Interaktion). Das Diagramm spezifiziert die strukturelle Einbettung von Kommunikationsspezifikationen (<code>ServerComSpec</code>) an Bereitstellungs-Ports (<code>PPortPrototype</code>) innerhalb von Komponenten-Typen sowie die Import-Beziehung aus dem Verhaltensmodellierungs-Kontext (<code>BM Environment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metamodell-Klassen, Pakete und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Aggregiert über eine Komposition mit Rollenbezeichnung <code>+component</code> und Kardinalität <code>0..*</code> die Port-Prototypen (<code>+ports</code>).</li>\n<li><code>Components::PortPrototype</code>: Abstrakte Basisklasse, erbt von <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code> und <code>PropertyEvaluator</code>.</li>\n<li><code>Components::PPortPrototype</code>: Spezialisiert <code>Components::PortPrototype</code> (Generalisierung) und aggregiert über eine Komposition mit Rollenbezeichnung <code>+comSpec</code> und Kardinalität <code>0..*</code> Kommunikationsspezifikationen vom Typ <code>Communication::PPortComSpec</code>.</li>\n<li><code>Communication::PPortComSpec</code>: Abstrakte Basisklasse für Bereitstellungs-Port-Spezifikationen.</li>\n<li><code>Communication::ServerComSpec</code>: Spezialisiert <code>Communication::PPortComSpec</code> (Generalisierung). Besitzt das Attribut <code>+ queueLength: Int</code>.</li>\n<li><code>BM Environment</code> (Stereotyp bzw. Paket-Herkunft <code>(from Behavior Modeling)</code>): Referenziert <code>Communication::PPortComSpec</code> über eine Abhängigkeit (<code>&lt;&lt;dependency&gt;&gt;</code>) und importiert <code>Communication::ServerComSpec</code> über eine gerichtete Abhängigkeit mit dem Stereotyp <code>&lt;&lt;import&gt;&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeit- oder Sequenzabläufe. Die funktionale Semantik definiert zur Entwurfs- bzw. Konfigurationszeit, dass eine serverseitige Client-Server-Schnittstelle über einen <code>PPortPrototype</code> eine Pufferkapazität (<code>queueLength</code>) für eingehende Aufrufe vorhält, welche von der Modellierungsumgebung (<code>BM Environment</code>) für die Generierung oder Kopplung von Verhaltensmodellen importiert und ausgewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für AUTOSAR-Autorensysteme, Generatoren und Verhaltensmodellierungs-Werkzeuge. <code>ServerComSpec</code> definiert die Warteschlangenlänge (<code>queueLength</code>) für Client-Server-Operationen am Server-Port. Werkzeuge der Verhaltensmodellierung (<code>BM Environment</code>) müssen bei der Schnittstellen-Transformation oder Codegenerierung diesen Integer-Wert auswerten, um die Pufferung gleichzeitiger oder asynchroner Client-Aufrufe spezifikationskonform zu dimensionieren. Fehlt eine <code>ServerComSpec</code> oder ist <code>queueLength</code> nicht definiert, greifen plattformspezifische Standardwerte des RTE-Generators.</p>"}], "trans": [{"from": "FIG-d4edf3069d283f67", "to": "FIG-8b8675688b79fd7d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
